 if(interval){const width=Math.max(3,x(event.end)-x(event.start));box.setAttribute('x',x(event.start));box.setAttribute('width',width);const text=group.querySelector('.event-label');if(text){text.setAttribute('x',x(event.start)+7);text.setAttribute('visibility',width>75?'visible':'hidden')}}
