 return editEvent(where,()=>{if(record.kind==='analysis_event')Object.assign(record,timing);else record.analysis_override=validateOverride({...record.analysis_override,...timing,unit:original.unit,note:original.note||'',reason:original.reason||'Timeline '+label+'（分析假设）',parameters:record.analysis_override?.parameters??record.raw_value??{},deleted:false,timing_status:'analyst_hypothesis'})},label);
