function readExecutionSummary(source){const key=source.id+'|'+source.sha256;if(!executionCache.has(key)){const promise=request('/api/source/'+encodeURIComponent(source.id)).then(envelope=>freezeDeep(parseExecutionSource(source,envelope,state.source.game_build))).catch(error=>{executionCache.delete(key);throw error;});executionCache.set(key,promise);}return executionCache.get(key);}
