function findSequence(objectId,sequenceId){return objectList().find(o=>o.id===objectId)?.sequences?.find(s=>s.id===sequenceId);}
function showEditor(event,sequence){if(state.mode!=='analysis'||!sequence)return;$('editor-pane').hidden=false;const effective=event?effectiveEvent(event,sequence,true):{start:null,end:null,unit:null,note:'',reason:''};$('edit-start').value=finite(effective.start)?effective.start:'';$('edit-end').value=finite(effective.end)?effective.end:'';$('edit-unit').value=UNITS.has(effective.unit)?effective.unit:'';$('edit-note').value=effective.note||'';$('edit-reason').value=effective.reason||'';$('edit-parameters').value=JSON.stringify(event?.analysis_override?.parameters??event?.parameters??event?.raw_value??{},null,2);const isNew=state.selection.kind==='new-event';$('new-event-fields').hidden=!isNew;$('edit-label').value=isNew?'':event?.label||'';$('edit-track').value=isNew?'分析事件':event?.track||'分析事件';$('reset-event').disabled=isNew||event?.kind==='analysis_event';$('delete-event').disabled=isNew;$('delete-event').textContent=event?.kind==='analysis_event'?'删除新增事件':'在副本中隐藏事件';$('event-editor').querySelector('[type=submit]').textContent=isNew?'新增事件':'应用修改';state.editorBase=editorValues();}
function editorValues(){return{start:$('edit-start').value,end:$('edit-end').value,unit:$('edit-unit').value,note:$('edit-note').value,reason:$('edit-reason').value,parameters:$('edit-parameters').value,label:$('edit-label').value,track:$('edit-track').value};}
