function startNewEvent(object,sequence,role){if(!canEdit()||!commitPending(false))return;state.selection={kind:'new-event',role,objectId:object.id,sequenceId:sequence.id};state.activeRole=role;renderInspector();$('edit-label').focus();}
async function saveAnalysis(){if(state.saving||timelineGesture||!commitPending(false))return;if(!state.analysis||state.stale){notice('来源版本已经变化，当前副本仍可读取与导出。','error');return}state.saving=true;updateStatus();try{validateAnalysis(state.analysis,state.source,false);const result=await request('/api/analyses',{method:'POST',body:JSON.stringify({expected_revision:state.analysis.revision,analysis:state.analysis})});state.analysis=clone(result.analysis||{...state.analysis,revision:result.revision});editHistory.markSaved(state.analysis);state.dirty=false;state.pending=false;notice('已保存 · 修订 '+result.revision+' · '+new Date(result.saved_at).toLocaleString('zh-CN',{hour12:false}),'success')}catch(error){notice(error.message,'error')}finally{state.saving=false;render()}}
async function openAnalyses(){const dialog=$('analyses-dialog'),list=$('analyses-list');list.replaceChildren(el('p','muted','读取已保存副本'));dialog.showModal();try{const result=await request('/api/analyses');list.replaceChildren();for(const item of result.analyses||[]){const row=el('div','analysis-item'),copy=el('div');copy.append(el('strong','',item.name||item.analysis_id),el('p','',`修订 ${item.revision} · ${item.saved_at?new Date(item.saved_at).toLocaleString('zh-CN',{hour12:false}):''}`));row.append(copy,button('打开',()=>loadAnalysis(item.analysis_id)));list.append(row);}if(!list.children.length)list.append(el('p','empty','还没有已保存的分析副本。'));}catch(error){list.replaceChildren(el('p','empty',error.message));}}
async function loadAnalysis(id){if(state.saving||timelineGesture)return;if((state.dirty||state.pending)&&!confirm('当前副本有未保存内容。打开其他副本会替换当前编辑，是否继续？'))return;try{const result=await request('/api/analyses/'+encodeURIComponent(id));validateAnalysis(result,state.source,false);state.analysis=clone(result);editHistory.reset(state.analysis.analysis_id);state.mode='analysis';state.stale=result.parent_package_fingerprint!==state.source.package_fingerprint||Boolean(result.validity?.stale_package||result.validity?.stale_build);state.dirty=false;state.pending=false;state.selection=null;$('analyses-dialog').close();render();notice(state.stale?'副本已打开，来源版本发生变化；保留原值供核对。':'已打开保存的分析副本。',state.stale?'error':'success');}catch(error){notice(error.message,'error');}}
function saveAs(){if(state.saving||timelineGesture||!commitPending(false)||!state.analysis)return;state.analysis=clone(state.analysis);state.analysis.analysis_id=crypto.randomUUID();state.analysis.name+=' 副本';state.analysis.revision=0;editHistory.reset(state.analysis.analysis_id,true);state.mode='analysis';state.dirty=true;render();notice('已创建另一份分析副本，保存后成为正式文件。');}
function exportAnalysis(){if(!commitPending(false)||!state.analysis)return;const blob=new Blob([JSON.stringify(state.analysis,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=state.analysis.analysis_id+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('已导出分析 JSON。');}
async function importFile(event){if(state.saving||timelineGesture)return;const file=event.target.files?.[0];if(!file)return;try{if(file.size>16*1024*1024)throw new Error('分析 JSON 超出 16 MiB，请缩小附件范围。');const value=JSON.parse(await file.text());validateFiniteJSON(value);validateAnalysis(value,state.source,true);if((state.dirty||state.pending)&&!confirm('导入会替换当前未保存副本，是否继续？'))return;state.analysis=clone(value);editHistory.reset(state.analysis.analysis_id,true);state.mode='analysis';state.stale=false;state.dirty=true;state.pending=false;state.selection=null;render();notice('分析 JSON 已导入，保存后写入正式文件。');}catch(error){notice(error.message,'error');}finally{event.target.value='';}}
async function openSource(id){const dialog=$('source-dialog'),host=$('source-content');host.className='source-content';host.replaceChildren(el('p','muted','读取来源记录'));if(!dialog.open)dialog.showModal();try{const result=await request('/api/source/'+encodeURIComponent(id));host.replaceChildren();host.append(el('h3','',id),dataList([['原始路径',result.source?.original_path||result.path||result.source?.path],['快照路径',result.source?.snapshot_path||result.source?.path],['来源状态',labelStatus(result.validity?.status||result.source?.status)],['当前 SHA256',result.validity?.sha256||result.sha256],['期望 SHA256',result.validity?.expected_sha256||result.source?.sha256],['定位',result.source?.locator],['读取方法',result.source?.method||result.source?.hash_scope]]));if(['changed','missing','unavailable'].includes(result.validity?.status))host.append(el('p','warning','来源状态已经变化；当前分析不能作为已确认时间。'));if(result.content!==null&&result.content!==undefined){const details=el('details','details');details.open=true;details.append(el('summary','','原始内容'),el('pre','',valueText(result.content)));host.append(details);}if(result.preview_hex)host.append(dataList([['二进制预览',result.preview_hex]]));if(result.preview_truncated)host.append(el('p','muted small','预览受读取上限限制，来源记录保留完整路径与文件哈希。'));}catch(error){host.replaceChildren(el('p','empty',error.message));}}
function renderResearch(){const q=$('research-search').value.trim().toLowerCase(),records=(state.research?.objects||[]).filter(o=>JSON.stringify([o.id,o.name,o.summary,o.fields]).toLowerCase().includes(q)),host=$('research-records');host.replaceChildren(el('p','muted small',records.length+' 条研究记录'));for(const object of records.slice(0,100)){const details=el('details','details'),summary=el('summary','',object.name||object.id);summary.append(el('span','badge',object.kind||'记录'));details.append(summary);if(object.summary)details.append(el('p','',object.summary));details.append(dataList([['对象 ID',object.id],['证据状态',labelStatus(object.status)],...(object.fields||[]).map(f=>[f.label||f.name||f.id,{value:f.value,unit:f.unit,status:f.status,locator:f.locator}])]),sourceButtons([...(object.source_ids||[]),...(object.fields||[]).flatMap(f=>f.source_ids||[])]));host.append(details);}if(records.length>100)host.append(el('p','muted','缩小搜索范围可查看其余记录。'));}
function addEditorFields(){const form=$('event-editor'),fields=el('div','new-event-fields');fields.id='new-event-fields';fields.hidden=true;for(const[name,id]of[['事件名称','edit-label'],['轨道','edit-track']]){const label=el('label','',name),input=el('input');input.id=id;label.append(input);fields.append(label);}form.prepend(fields);const label=el('label','','分析参数 JSON'),params=el('textarea','mono');params.id='edit-parameters';params.rows=5;params.spellcheck=false;label.append(params);form.insertBefore(label,form.querySelector('.editor-actions'));const remove=button('删除分析事件',deleteEvent);remove.id='delete-event';form.querySelector('.editor-actions').append(remove);}
function deleteEvent(){if(!canEdit())return;const selected=rawSelected();if(!selected?.record||!selected.sequence)return;try{const override=selected.record.kind==='analysis_event'?null:parsedEditor();editEvent(state.selection,()=>{if(selected.record.kind==='analysis_event')selected.sequence.analysis_events=selected.sequence.analysis_events.filter(e=>e.id!==selected.record.id);else selected.record.analysis_override={...override,deleted:true}},'移除分析事件');state.selection=null;render();notice('事件已从分析视图移除，尚未保存。')}catch(error){notice(error.message,'error')}}
function activateRole(role){if(!commitPending(false))return;rememberSubject();previewSeek.cancel();state.activeRole=role;state.selection=null;render();}
function bind(){addEditorFields();$('undo-edit').addEventListener('click',()=>restoreEdit('undo'));$('redo-edit').addEventListener('click',()=>restoreEdit('redo'));$('action-select').addEventListener('change',e=>chooseAction(e.target.value));$('variant-select').addEventListener('change',e=>chooseVariant(e.target.value));$('object-search').addEventListener('input',e=>{state.q=e.target.value;renderBrowser();});$('mode-original').addEventListener('click',()=>switchMode('original'));$('mode-analysis').addEventListener('click',()=>switchMode('analysis'));$('save-analysis').addEventListener('click',saveAnalysis);$('open-analyses').addEventListener('click',openAnalyses);$('save-as').addEventListener('click',saveAs);$('export-analysis').addEventListener('click',exportAnalysis);$('import-analysis').addEventListener('click',()=>$('import-file').click());$('import-file').addEventListener('change',importFile);$('event-editor').addEventListener('submit',e=>{e.preventDefault();try{applyEditor();}catch(error){notice(error.message,'error');}});$('event-editor').addEventListener('input',()=>{state.pending=editorChanged();updateStatus();});$('reset-event').addEventListener('click',()=>{if(!canEdit())return;const selected=rawSelected();if(!selected?.record||selected.record.kind==='analysis_event')return;editEvent(state.selection,()=>selected.record.analysis_override=null,'恢复事件原始值');render();seekSelectedPreview();notice('已恢复当前事件的原始值，尚未保存。');});$('browse-research').addEventListener('click',()=>{$('research-dialog').showModal();renderResearch();});$('research-search').addEventListener('input',renderResearch);document.querySelectorAll('[data-close]').forEach(n=>n.addEventListener('click',()=>$((n.dataset.close)).close()));for(const role of['character','boss'])$('role-'+role).addEventListener('click',()=>activateRole(role));document.querySelector('.role-filters').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?'character':e.key==='End'?'boss':state.activeRole==='character'?'boss':'character';activateRole(next);$('role-'+state.activeRole).focus();});window.addEventListener('beforeunload',e=>{if(state.dirty||state.pending){e.preventDefault();e.returnValue='';}});document.addEventListener('keydown',e=>{const typing=e.target.closest?.('input,textarea,select,[contenteditable]');if(!typing&&!document.querySelector('dialog[open]')&&(e.ctrlKey||e.metaKey)&&!e.altKey&&['z','y'].includes(e.key.toLowerCase())&&canEdit()){e.preventDefault();restoreEdit(e.key.toLowerCase()==='y'||e.shiftKey?'redo':'undo');return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();if(state.mode==='analysis')saveAnalysis();}});}
async function main(){bind();assetViewer=new AssetViewer($('asset-preview'),{openSource,onTime:updatePreviewCursor,transportHost:$('editor-transport'),detailsHost:$('preview-asset-details')});try{const[research,timelines]=await Promise.all([request('/api/research'),request('/api/timelines')]);if(research.schema_version!==1||timelines.schema_version!=='timeline-source/1'||!Array.isArray(timelines.objects))throw new Error('本地数据格式不匹配。');state.research=freezeDeep(research);state.source=freezeDeep(timelines);for(const role of['character','boss'])state.roleSelection[role]=timelines.objects.find(o=>o.role===role)?.id||null;$('identity').textContent='Build '+timelines.game_build+' · 玩家版本 '+(research.game?.version==='unknown'?'未知':research.game?.version||'未知');render();notice('本地证据已读取。');loadPreviewManifest();}catch(error){notice(error.message,'error');$('identity').textContent='本地数据未加载';for(const role of['character','boss'])$('window-'+role).append(el('p','empty','检查本地服务与研究数据后重新加载。'));}}
function syncPreviewContext(){if(!assetViewer||!state.source)return;if(state.mode==='analysis'&&state.stale){previewSeek.cancel();assetViewer.clear();assetViewer.context=null;assetViewer.contextKey=null;assetViewer.assetPicker.replaceChildren();assetViewer.disable('该分析副本来源版本已变化。切回原始事件可查看当前模型，旧副本保留供核对。');return;}const object=currentObject(state.activeRole),sequence=currentSequence(object);if(!object||!sequence)return;return assetViewer.setContext({objectId:object.id,sequenceId:sequence.id,role:state.activeRole,objectName:previewName(object)});}
async function loadPreviewManifest(){try{const manifest=await request('/api/preview');previewSeek.cancel();if(state.mode==='analysis'&&state.stale)assetViewer.context=null;assetViewer.setManifest(freezeDeep(manifest),state.source);syncPreviewContext();}catch(error){assetViewer.disable('预览登记暂不可用：'+error.message);}}
function previewContextCurrent(context){const object=currentObject(state.activeRole),sequence=currentSequence(object);return !(state.mode==='analysis'&&state.stale)&&state.activeRole===context.role&&object?.id===context.objectId&&sequence?.id===context.sequenceId;}
async function seekTimelinePreview(object,sequence,role,time,unit){if(!assetViewer||state.mode==='analysis'&&state.stale||!commitPending(false))return false;state.activeRole=role;state.roleSelection[role]=object.id;state.sequenceSelection.set(object.id,sequence.id);render();const context={objectId:object.id,sequenceId:sequence.id,role,objectName:previewName(object)};return previewSeek.seek(assetViewer,context,time,unit,()=>previewContextCurrent(context));}
async function seekSelectedPreview(){const selected=rawSelected();if(!selected?.record||!selected.sequence||state.selection?.kind!=='event'||state.mode==='analysis'&&state.stale)return;const event=effectiveEvent(selected.record,selected.sequence,state.mode==='analysis');if(isTimed(event,selected.sequence)&&!affected(event)){const context={objectId:selected.object.id,sequenceId:selected.sequence.id,role:state.selection.role,objectName:previewName(selected.object)};return previewSeek.seek(assetViewer,context,event.start,event.unit,()=>previewContextCurrent(context));}}
function updatePreviewCursor(value){$('timeline-time').textContent=finite(value.actionTime)?formatNumber(value.actionTime)+' '+unitLabel(value.unit)+' · 动作':'动作坐标未对应';for(const svg of document.querySelectorAll('svg[data-preview-object]')){const line=svg.querySelector('[data-preview-cursor]');if(!line)continue;const matches=value.objectId===svg.dataset.previewObject&&value.sequenceId===svg.dataset.previewSequence&&value.unit===svg.dataset.previewUnit&&finite(value.actionTime),low=Number(svg.dataset.axisLow),high=Number(svg.dataset.axisHigh);if(!matches||value.actionTime<low||value.actionTime>high){line.setAttribute('visibility','hidden');continue;}const width=Number(svg.dataset.axisWidth)||560,labelWidth=Number(svg.dataset.axisLabelWidth)||112,x=labelWidth+(value.actionTime-low)/(high-low)*(width-labelWidth-16);line.setAttribute('x1',x);line.setAttribute('x2',x);line.setAttribute('visibility','visible');}}

// Resize the axis with its dock without replacing an in-progress form or gesture.
let observedWorkspaceWidth=0,layoutFrame=0;
new ResizeObserver(entries=>{const width=Math.round(entries[0].contentRect.width);if(width===observedWorkspaceWidth)return;observedWorkspaceWidth=width;cancelAnimationFrame(layoutFrame);layoutFrame=requestAnimationFrame(()=>{if(state.source&&!state.pending&&!timelineGesture&&!state.saving)render()})}).observe($('workspaces'));
main();
